using UnityEngine; using System; namespace HonourWar { public sealed class HonourWarPlayerController:MonoBehaviour { public HonourWarCharacter Character; public string ExecuteCommand(string raw){if(Character==null)return "No character";var p=(raw??"").Trim().Split(' ');if(p.Length>=3&&p[0].Equals("@go",StringComparison.OrdinalIgnoreCase)){var xy=p[2].Split(':');if(xy.Length==2&&float.TryParse(xy[0],out var x)&&float.TryParse(xy[1],out var z)){Character.Teleport(new Vector3(x/10f,Character.transform.position.y,z/10f));return $"@go {p[1]} {x}:{z} executed";}}if(p.Length>0&&p[0].Equals("@help",StringComparison.OrdinalIgnoreCase))return "@go MAP X:Y | @help | @restskills";return "Unknown command";} } }